import{_ as r,K as l,a as s,c as d,ac as e,b as o,q as n}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"篮球规则 · 人数、场地与得分至身体接触与犯规处罚","description":"以 FIBA 2026 年五人制规则理解篮球计分、比赛流程、违例、犯规与常见判例","frontmatter":{"title":"篮球规则 · 人数、场地与得分至身体接触与犯规处罚","description":"以 FIBA 2026 年五人制规则理解篮球计分、比赛流程、违例、犯规与常见判例","splitFrom":"life/personal/sports/basketball-rules.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"篮球规则","summary":"以 FIBA 2026 年五人制规则理解篮球计分、比赛流程、违例、犯规与常见判例","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"篮球规则","link":"/life/personal/sports/basketball-rules"},"next":{"text":"篮球规则 · 常见判例与误解至官方资料与阅读范围","link":"/life/personal/sports/basketball-rules-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"篮球规则","link":"/life/personal/sports/basketball-rules"},"next":{"text":"篮球规则 · 常见判例与误解至官方资料与阅读范围","link":"/life/personal/sports/basketball-rules-part-02"}},"headers":[],"relativePath":"life/personal/sports/basketball-rules-part-01.md","filePath":"life/personal/sports/basketball-rules-part-01.md"}'),i={name:"life/personal/sports/basketball-rules-part-01.md"};function p(h,t,b,u,c,g){const a=l("ArticleImage");return s(),d("div",null,[t[0]||(t[0]=e('<h1 id="篮球规则-·-人数、场地与得分至身体接触与犯规处罚" tabindex="-1">篮球规则 · 人数、场地与得分至身体接触与犯规处罚 <a class="header-anchor" href="#篮球规则-·-人数、场地与得分至身体接触与犯规处罚" aria-label="Permalink to &quot;篮球规则 · 人数、场地与得分至身体接触与犯规处罚&quot;">​</a></h1><p><a href="/life/personal/sports/basketball-rules">返回分篇目录</a></p><p>篮球比赛的目标是在规定时间内获得更多分数。看懂比赛，先区分两件事：<strong>违例通常导致球权转换，犯规还可能涉及罚球、个人累计和纪律处罚</strong>。</p><p>本文采用 FIBA《Official Basketball Rules 2026》v1.1，自 <strong>2026 年 10 月 1 日</strong>起生效；适用标准五人制篮球。NBA、FIBA 三人篮球、青少年和校园赛事另有规则，不能把不同体系混在一起。文中对 2026 年新增犯规类型保留英文名称，中文采用解释性译法。</p><h2 id="篮球规则" tabindex="-1">篮球规则 <a class="header-anchor" href="#篮球规则" aria-label="Permalink to &quot;篮球规则 {#篮球规则}&quot;">​</a></h2><p>篮球比赛的目标是在规定时间内获得更多分数。看懂比赛，先区分两件事：<strong>违例通常导致球权转换，犯规还可能涉及罚球、个人累计和纪律处罚</strong>。</p><p>本文采用 FIBA《Official Basketball Rules 2026》v1.1，自 <strong>2026 年 10 月 1 日</strong>起生效；适用标准五人制篮球。NBA、FIBA 三人篮球、青少年和校园赛事另有规则，不能把不同体系混在一起。文中对 2026 年新增犯规类型保留英文名称，中文采用解释性译法。</p><p>最容易混淆的是：NBA 每节通常为 12 分钟、个人 6 次犯规离场；本文是每节 10 分钟、5 次犯规离场。FIBA 三人篮球使用半场单篮筐，采用 1 分／2 分计分及独立的比赛、进攻时限，不适用下文的四节和两分／三分体系。</p><h2 id="人数、场地与得分" tabindex="-1">人数、场地与得分 <a class="header-anchor" href="#人数、场地与得分" aria-label="Permalink to &quot;人数、场地与得分 {#人数、场地与得分}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>FIBA 五人制基本规定</th></tr></thead><tbody><tr><td>场上人数</td><td>每队 5 人；球队最多 12 名有参赛资格的队员</td></tr><tr><td>场地</td><td>长 28 米、宽 15 米，从边界线内沿测量</td></tr><tr><td>篮圈高度</td><td>篮圈上沿距地面 3.05 米</td></tr><tr><td>三分线</td><td>圆弧半径 6.75 米，底角由直线连接；三分线本身属于两分区域</td></tr><tr><td>正式比赛时间</td><td>4 节，每节 10 分钟；常规时间平分后打 5 分钟加时，直到分出胜负</td></tr><tr><td>得分</td><td>罚球 1 分，两分区域投篮 2 分，三分区域投篮 3 分</td></tr><tr><td>个人犯规上限</td><td>累计 5 次犯规后离场，由替补队员替换</td></tr></tbody></table><p>判断投篮值几分，看投球队员出手时的位置。腾空队员的位置由最后触地处决定：在三分线外合法起跳，空中出手后落在三分线内，命中仍可算 3 分；起跳前踩线，则算 2 分。</p><p>边界线不属于场内。球或持球队员触及边界线、界外地面等，即可能出界；通常由最后触球队员的对方掷球入界。</p><h2 id="看图识别场地" tabindex="-1">看图识别场地 <a class="header-anchor" href="#看图识别场地" aria-label="Permalink to &quot;看图识别场地 {#看图识别场地}&quot;">​</a></h2>',13)),o("p",null,[n(a,{src:"/images/sports/basketball-court.svg",alt:"FIBA 篮球场比例图：两端限制区、三分线和中线"})]),t[1]||(t[1]=e('<p><em>图：按 28 × 15 米绘制的主要区域，深色圆点是篮圈中心投影；省略罚球站位标记、无撞人半圆等细节，线宽经过放大，不用于施工。棕色线内及线上属于两分区域，线外是三分区域。</em></p><p>看图时先找自己要进攻的篮筐，再辨认限制区和三分线。浅蓝限制区关系到进攻三秒与罚球站位，<strong>不是“进去就只能停三秒”的无条件禁区</strong>：必须同时满足本队前场控球、比赛钟运行等条件。图上中线两侧的前后场身份随进攻方向改变，不是固定指上半张或下半张。</p><h2 id="一场比赛怎样进行" tabindex="-1">一场比赛怎样进行 <a class="header-anchor" href="#一场比赛怎样进行" aria-label="Permalink to &quot;一场比赛怎样进行 {#一场比赛怎样进行}&quot;">​</a></h2><p>第一节以中圈跳球开始。之后的争球情况，以及第二、第三、第四节和加时的开场，通常采用<strong>交替拥有球权</strong>，由球权箭头决定掷球入界的一方，不是每次争球都重新跳球。</p><p>进攻方通过传球、运球和投篮推进。得分后，由失分一方在本方端线后掷球入界；普通违例或犯规后的入界位置，则由对应处罚决定。裁判鸣哨后应先停止动作，确认手势、记录台和入界位置。</p><p>比赛计时并非一直走表。裁判鸣哨、节末等情况下停表；第四节和每次加时最后 2 分钟内的投篮得分也停表。业余活动常用不停表计时，应在赛前约定，不能据此理解正式比赛。</p><p>换人须在允许的换人机会，经记录台和裁判程序进行。每次暂停 1 分钟：上半场可用 2 次，下半场可用 3 次，但第四节最后 2 分钟最多使用其中 2 次；每次加时可用 1 次。未用暂停不能结转到下半场或下一次加时。</p><h2 id="先记住五组时间限制" tabindex="-1">先记住五组时间限制 <a class="header-anchor" href="#先记住五组时间限制" aria-label="Permalink to &quot;先记住五组时间限制 {#先记住五组时间限制}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>如何理解</th><th>常见误区</th></tr></thead><tbody><tr><td>24 秒</td><td>球队取得场上活球控制后，须在时限内完成一次符合条件的投篮</td><td>只把球投出去不够；球须在信号前离手，之后进入篮筐或触及篮圈</td></tr><tr><td>14 秒</td><td>例如投篮碰对方篮圈后，原进攻队再次获得控制，进攻计时重置为 14 秒</td><td>防守队仅将球碰出界，不会自动给进攻方新的 14 秒</td></tr><tr><td>8 秒</td><td>后场取得控制后，须在 8 秒内使球进入前场</td><td>运球队员过中线要看球和双脚是否都已进入前场</td></tr><tr><td>3 秒</td><td>本队在前场控制活球且比赛钟运行时，进攻队员不得在对方限制区连续停留超过 3 秒</td><td>FIBA 没有 NBA 式防守三秒；投篮、离开限制区等情形有具体判定条件</td></tr><tr><td>5 秒</td><td>掷球入界、执行罚球有 5 秒限制；场上持球受到 1 米内积极合法严密防守时，也须在 5 秒内传、投或开始运球</td><td>不能把所有原地持球都视为“五秒违例”</td></tr></tbody></table><p>例如投篮出手后球只碰篮板，没有碰篮圈，进攻队拿回球不因此获得新的进攻时间。若进攻计时已到且不符合投篮条件，应判违例。</p><h2 id="运球、走步和回场" tabindex="-1">运球、走步和回场 <a class="header-anchor" href="#运球、走步和回场" aria-label="Permalink to &quot;运球、走步和回场 {#运球、走步和回场}&quot;">​</a></h2><h3 id="运球结束后不能随意重新开始" tabindex="-1">运球结束后不能随意重新开始 <a class="header-anchor" href="#运球结束后不能随意重新开始" aria-label="Permalink to &quot;运球结束后不能随意重新开始 {#运球结束后不能随意重新开始}&quot;">​</a></h3><p>双手同时触球，或球停留在一手或双手中，通常意味着本次运球已经结束。之后再次运球，通常构成两次运球。2026 版第 24 条明确，重新运球的例外涉及此前因投篮、对手触球，或传球／漏接时球接触另一名队员而失去控制等情况；自己把球抛起再接住，不能自动获得一次新运球机会。</p><h3 id="走步看控制球时刻和脚步" tabindex="-1">走步看控制球时刻和脚步 <a class="header-anchor" href="#走步看控制球时刻和脚步" aria-label="Permalink to &quot;走步看控制球时刻和脚步 {#走步看控制球时刻和脚步}&quot;">​</a></h3><p>站定接球后，一只脚成为中枢脚，另一只脚可以移动。开始运球时，球必须先离手，再抬起中枢脚；传球或投篮可以抬起中枢脚，但球离手前不能让脚重新落地。</p><p>移动中接球或结束运球后，规则允许按规定使用两步完成停步、传球或投篮。第一步是取得控制后的一脚或双脚触地，不能只看录像里脚落地几次而忽略何时控制球。所谓“上篮能走三步”不是准确的规则表述。</p><h3 id="回场需要满足控制与触球条件" tabindex="-1">回场需要满足控制与触球条件 <a class="header-anchor" href="#回场需要满足控制与触球条件" aria-label="Permalink to &quot;回场需要满足控制与触球条件 {#回场需要满足控制与触球条件}&quot;">​</a></h3><p>本队已在前场控制活球，若本队最后在前场触球，又由本队首先在后场触球，通常构成球非法返回后场。防守方将球碰回后场，进攻方可以追取；空中截获对手传球后落回本方后场等情况，也有明确例外，不能只凭“球过了中线又回来”判罚。</p><h2 id="身体接触与犯规处罚" tabindex="-1">身体接触与犯规处罚 <a class="header-anchor" href="#身体接触与犯规处罚" aria-label="Permalink to &quot;身体接触与犯规处罚 {#身体接触与犯规处罚}&quot;">​</a></h2><p>身体接触不一定都是犯规。防守队员有权占据合法位置，并在自身圆柱体内垂直起跳；伸手拉拽、推人、非法阻挡、撞击已经建立合法防守位置的对手，可能构成侵人犯规。掩护者也必须遵守位置、时间和距离要求，不能移动身体去撞挡对手。</p><table tabindex="0"><thead><tr><th>情形</th><th>一般处罚</th></tr></thead><tbody><tr><td>对非投篮队员的普通侵人犯规，尚未进入全队犯规处罚状态</td><td>对方掷球入界</td></tr><tr><td>对正在投篮队员犯规，球投中</td><td>得分有效，并追加 1 次罚球</td></tr><tr><td>对正在投篮队员犯规，球未投中</td><td>按出手区域罚 2 次或 3 次</td></tr><tr><td>一节全队已有 4 次犯规，随后再对非投篮队员发生普通侵人犯规</td><td>通常给被犯规队员 2 次罚球</td></tr><tr><td>控球队或有权掷球入界球队的普通侵人犯规</td><td>对方掷球入界，不因全队犯规已满改成罚球</td></tr></tbody></table><p>加时的全队犯规计入第四节，不重新清零。投篮动作的开始也不是“把球拿起来就算”：2026 版区分跳投／其他移动投篮和突破上篮，通常要求进攻队员处于前场；节末或进攻时限结束前最后一次出手另有例外。</p><h3 id="_2026-年的犯规分类变化" tabindex="-1">2026 年的犯规分类变化 <a class="header-anchor" href="#_2026-年的犯规分类变化" aria-label="Permalink to &quot;2026 年的犯规分类变化 {#_2026-年的犯规分类变化}&quot;">​</a></h3><p>旧规则常说的 unsportsmanlike foul 已拆分为 <strong>Disruptive foul</strong> 和 <strong>Flagrant foul</strong>。看旧教材或旧比赛时，应核对采用的版本。</p><ul><li><strong>Disruptive foul（破坏比赛进程的犯规）</strong>：如不合法争抢球、以不必要接触阻止转换进攻，或符合条文条件的身后／侧面阻断直奔篮下机会。一般按情况罚球后，再给予前场掷球入界；它不计入特定两次犯规自动取消资格的组合，但仍计个人和全队犯规。</li><li><strong>Flagrant foul（严重违反体育精神的犯规）</strong>：如危险、鲁莽、暴力动作，或过度猛烈接触。按情况罚球并保留球权，且计入取消比赛资格的累计。</li><li><strong>技术犯规</strong>：2026 版分为第 1 类和第 2 类，一般罚给对方 1 次罚球，再按规则恢复原有比赛状态。第 1 类如辱骂、挑衅、假摔等；第 2 类如部分拖延比赛或行政性质行为。队员的两类技术犯规均计个人及全队犯规，但只有第 1 类计入下述取消资格组合。</li></ul><p>队员累计 <strong>2 次第 1 类技术犯规、2 次 Flagrant foul，或各 1 次</strong>，被取消本场余下比赛资格。严重恶劣行为也可能直接判取消比赛资格犯规。不能继续套用“任何两次技术犯规一律驱逐”的旧概括。</p>',26))])}const m=r(i,[["render",p]]);export{k as __pageData,m as default};
